{
  "findings": [
    {
      "check_id": "CKV_AWS_2",
      "title": "Ensure ALB protocol is HTTPS",
      "resource": "aws_lb_listener.webserver_listner",
      "severity": "MEDIUM",
      "explanation": "The listener is configured to use the HTTP protocol on port 80, which does not encrypt traffic. This exposes data in transit to potential interception."
    },
    {
      "check_id": "CKV_AWS_378",
      "title": "Ensure AWS Load Balancer doesn't use HTTP protocol",
      "resource": "aws_lb_listener.webserver_listner",
      "severity": "MEDIUM",
      "explanation": "The listener is using the HTTP protocol, which is insecure and should be replaced with HTTPS to ensure secure communication."
    },
    {
      "check_id": "CKV_AWS_376",
      "title": "Ensure AWS Elastic Load Balancer listener uses TLS/SSL",
      "resource": "aws_lb_listener.webserver_listner",
      "severity": "MEDIUM",
      "explanation": "The listener does not use TLS/SSL for secure communication, leaving the connection vulnerable to eavesdropping and man-in-the-middle attacks."
    }
  ],
  "patched_code": "resource \"aws_lb_listener\" \"webserver_listner\" {\n  load_balancer_arn = aws_lb.levelup-load-balancer.arn\n  port              = \"443\"\n  protocol          = \"HTTPS\"\n  ssl_policy        = \"ELBSecurityPolicy-2016-08\"\n  certificate_arn   = \"arn:aws:acm:region:account-id:certificate/certificate-id\"\n\n  default_action {\n    target_group_arn = aws_lb_target_group.load-balancer-target-group.arn\n    type             = \"forward\"\n  }\n}",
  "fix_summary": "Updated the listener to use HTTPS protocol on port 443, added an SSL policy, and specified a certificate ARN to ensure secure communication."
}
